fn all_sequence_equal_length(seq: &Vec<Vec<i32>>) -> bool {
    // If the outer vector is empty, we consider all (zero) inner arrays to have the same length.
    // Although the problem states that the outer list is non-empty, this makes the function more robust.
    if seq.is_empty() {
        return true;
    }

    // Take the length of the first inner array as the expected length.
    let expected_len = seq[0].len();

    // Check that every inner array has the same length.
    seq.iter().all(|inner| inner.len() == expected_len)
}

